mkitem!{mkenum!{# [doc = " Atomic memory orderings"] # [doc = ""] # [doc = " Memory orderings specify the way atomic operations synchronize memory."] # [doc = " In its weakest [`Ordering::Relaxed`], only the memory directly touched by the"] # [doc = " operation is synchronized. On the other hand, a store-load pair of [`Ordering::SeqCst`]"] # [doc = " operations synchronize other memory while additionally preserving a total order of such"] # [doc = " operations across all threads."] # [doc = ""] # [doc = " Rust's memory orderings are [the same as those of"] # [doc = " C++20](https://en.cppreference.com/w/cpp/atomic/memory_order)."] # [doc = ""] # [doc = " For more information see the [nomicon]."] # [doc = ""] # [doc = " [nomicon]: ../../../nomicon/atomics.html"] # [stable (feature = "rust1" , since = "1.0.0")] # [derive (Copy , Clone , Debug , Eq , PartialEq , Hash)] # [non_exhaustive] # [rustc_diagnostic_item = "Ordering"] pub enum Ordering { # [doc = " No ordering constraints, only atomic operations."] # [doc = ""] # [doc = " Corresponds to [`memory_order_relaxed`] in C++20."] # [doc = ""] # [doc = " [`memory_order_relaxed`]: https://en.cppreference.com/w/cpp/atomic/memory_order#Relaxed_ordering"] # [stable (feature = "rust1" , since = "1.0.0")] Relaxed , # [doc = " When coupled with a store, all previous operations become ordered"] # [doc = " before any load of this value with [`Acquire`] (or stronger) ordering."] # [doc = " In particular, all previous writes become visible to all threads"] # [doc = " that perform an [`Acquire`] (or stronger) load of this value."] # [doc = ""] # [doc = " Notice that using this ordering for an operation that combines loads"] # [doc = " and stores leads to a [`Relaxed`] load operation!"] # [doc = ""] # [doc = " This ordering is only applicable for operations that can perform a store."] # [doc = ""] # [doc = " Corresponds to [`memory_order_release`] in C++20."] # [doc = ""] # [doc = " [`memory_order_release`]: https://en.cppreference.com/w/cpp/atomic/memory_order#Release-Acquire_ordering"] # [stable (feature = "rust1" , since = "1.0.0")] Release , # [doc = " When coupled with a load, if the loaded value was written by a store operation with"] # [doc = " [`Release`] (or stronger) ordering, then all subsequent operations"] # [doc = " become ordered after that store. In particular, all subsequent loads will see data"] # [doc = " written before the store."] # [doc = ""] # [doc = " Notice that using this ordering for an operation that combines loads"] # [doc = " and stores leads to a [`Relaxed`] store operation!"] # [doc = ""] # [doc = " This ordering is only applicable for operations that can perform a load."] # [doc = ""] # [doc = " Corresponds to [`memory_order_acquire`] in C++20."] # [doc = ""] # [doc = " [`memory_order_acquire`]: https://en.cppreference.com/w/cpp/atomic/memory_order#Release-Acquire_ordering"] # [stable (feature = "rust1" , since = "1.0.0")] Acquire , # [doc = " Has the effects of both [`Acquire`] and [`Release`] together:"] # [doc = " For loads it uses [`Acquire`] ordering. For stores it uses the [`Release`] ordering."] # [doc = ""] # [doc = " Notice that in the case of `compare_and_swap`, it is possible that the operation ends up"] # [doc = " not performing any store and hence it has just [`Acquire`] ordering. However,"] # [doc = " `AcqRel` will never perform [`Relaxed`] accesses."] # [doc = ""] # [doc = " This ordering is only applicable for operations that combine both loads and stores."] # [doc = ""] # [doc = " Corresponds to [`memory_order_acq_rel`] in C++20."] # [doc = ""] # [doc = " [`memory_order_acq_rel`]: https://en.cppreference.com/w/cpp/atomic/memory_order#Release-Acquire_ordering"] # [stable (feature = "rust1" , since = "1.0.0")] AcqRel , # [doc = " Like [`Acquire`]/[`Release`]/[`AcqRel`] (for load, store, and load-with-store"] # [doc = " operations, respectively) with the additional guarantee that all threads see all"] # [doc = " sequentially consistent operations in the same order."] # [doc = ""] # [doc = " Corresponds to [`memory_order_seq_cst`] in C++20."] # [doc = ""] # [doc = " [`memory_order_seq_cst`]: https://en.cppreference.com/w/cpp/atomic/memory_order#Sequentially-consistent_ordering"] # [stable (feature = "rust1" , since = "1.0.0")] SeqCst , }}}
