mkfn!{
    fence_introspect!();
    # [doc = " An atomic fence."] # [doc = ""] # [doc = " Fences create synchronization between themselves and atomic operations or fences in other"] # [doc = " threads. To achieve this, a fence prevents the compiler and CPU from reordering certain types of"] # [doc = " memory operations around it."] # [doc = ""] # [doc = " A fence 'A' which has (at least) [`Release`] ordering semantics, synchronizes"] # [doc = " with a fence 'B' with (at least) [`Acquire`] semantics, if and only if there"] # [doc = " exist operations X and Y, both operating on some atomic object 'm' such"] # [doc = " that A is sequenced before X, Y is sequenced before B and Y observes"] # [doc = " the change to m. This provides a happens-before dependence between A and B."] # [doc = ""] # [doc = " ```text"] # [doc = "     Thread 1                                          Thread 2"] # [doc = ""] # [doc = " fence(Release);      A --------------"] # [doc = " m.store(3, Relaxed); X ---------    |"] # [doc = "                                |    |"] # [doc = "                                |    |"] # [doc = "                                -------------> Y  if m.load(Relaxed) == 3 {"] # [doc = "                                     |-------> B      fence(Acquire);"] # [doc = "                                                      ..."] # [doc = "                                                  }"] # [doc = " ```"] # [doc = ""] # [doc = " Note that in the example above, it is crucial that the accesses to `m` are atomic. Fences cannot"] # [doc = " be used to establish synchronization among non-atomic accesses in different threads. However,"] # [doc = " thanks to the happens-before relationship between A and B, any non-atomic accesses that"] # [doc = " happen-before A are now also properly synchronized with any non-atomic accesses that"] # [doc = " happen-after B."] # [doc = ""] # [doc = " Atomic operations with [`Release`] or [`Acquire`] semantics can also synchronize"] # [doc = " with a fence."] # [doc = ""] # [doc = " A fence which has [`SeqCst`] ordering, in addition to having both [`Acquire`]"] # [doc = " and [`Release`] semantics, participates in the global program order of the"] # [doc = " other [`SeqCst`] operations and/or fences."] # [doc = ""] # [doc = " Accepts [`Acquire`], [`Release`], [`AcqRel`] and [`SeqCst`] orderings."] # [doc = ""] # [doc = " # Panics"] # [doc = ""] # [doc = " Panics if `order` is [`Relaxed`]."] # [doc = ""] # [doc = " # Examples"] # [doc = ""] # [doc = " ```"] # [doc = " use std::sync::atomic::AtomicBool;"] # [doc = " use std::sync::atomic::fence;"] # [doc = " use std::sync::atomic::Ordering;"] # [doc = ""] # [doc = " // A mutual exclusion primitive based on spinlock."] # [doc = " pub struct Mutex {"] # [doc = "     flag: AtomicBool,"] # [doc = " }"] # [doc = ""] # [doc = " impl Mutex {"] # [doc = "     pub fn new() -> Mutex {"] # [doc = "         Mutex {"] # [doc = "             flag: AtomicBool::new(false),"] # [doc = "         }"] # [doc = "     }"] # [doc = ""] # [doc = "     pub fn lock(&self) {"] # [doc = "         // Wait until the old value is `false`."] # [doc = "         while self"] # [doc = "             .flag"] # [doc = "             .compare_exchange_weak(false, true, Ordering::Relaxed, Ordering::Relaxed)"] # [doc = "             .is_err()"] # [doc = "         {}"] # [doc = "         // This fence synchronizes-with store in `unlock`."] # [doc = "         fence(Ordering::Acquire);"] # [doc = "     }"] # [doc = ""] # [doc = "     pub fn unlock(&self) {"] # [doc = "         self.flag.store(false, Ordering::Release);"] # [doc = "     }"] # [doc = " }"] # [doc = " ```"] # [inline] # [stable (feature = "rust1" , since = "1.0.0")] # [rustc_diagnostic_item = "fence"] # [cfg_attr (miri , track_caller)] pub fn fence (order : Ordering) { unsafe { match order { Acquire => intrinsics :: atomic_fence :: < { AO :: Acquire } > () , Release => intrinsics :: atomic_fence :: < { AO :: Release } > () , AcqRel => intrinsics :: atomic_fence :: < { AO :: AcqRel } > () , SeqCst => intrinsics :: atomic_fence :: < { AO :: SeqCst } > () , Relaxed => panic ! ("there is no such thing as a relaxed fence") , } } }
}

