mkfn!{
    compiler_fence_introspect!();
    # [doc = " A \"compiler-only\" atomic fence."] # [doc = ""] # [doc = " Like [`fence`], this function establishes synchronization with other atomic operations and"] # [doc = " fences. However, unlike [`fence`], `compiler_fence` only establishes synchronization with"] # [doc = " operations *in the same thread*. This may at first sound rather useless, since code within a"] # [doc = " thread is typically already totally ordered and does not need any further synchronization."] # [doc = " However, there are cases where code can run on the same thread without being ordered:"] # [doc = " - The most common case is that of a *signal handler*: a signal handler runs in the same thread"] # [doc = "   as the code it interrupted, but it is not ordered with respect to that code. `compiler_fence`"] # [doc = "   can be used to establish synchronization between a thread and its signal handler, the same way"] # [doc = "   that `fence` can be used to establish synchronization across threads."] # [doc = " - Similar situations can arise in embedded programming with interrupt handlers, or in custom"] # [doc = "   implementations of preemptive green threads. In general, `compiler_fence` can establish"] # [doc = "   synchronization with code that is guaranteed to run on the same hardware CPU."] # [doc = ""] # [doc = " See [`fence`] for how a fence can be used to achieve synchronization. Note that just like"] # [doc = " [`fence`], synchronization still requires atomic operations to be used in both threads -- it is"] # [doc = " not possible to perform synchronization entirely with fences and non-atomic operations."] # [doc = ""] # [doc = " `compiler_fence` does not emit any machine code, but restricts the kinds of memory re-ordering"] # [doc = " the compiler is allowed to do. `compiler_fence` corresponds to [`atomic_signal_fence`] in C and"] # [doc = " C++."] # [doc = ""] # [doc = " [`atomic_signal_fence`]: https://en.cppreference.com/w/cpp/atomic/atomic_signal_fence"] # [doc = ""] # [doc = " # Panics"] # [doc = ""] # [doc = " Panics if `order` is [`Relaxed`]."] # [doc = ""] # [doc = " # Examples"] # [doc = ""] # [doc = " Without the two `compiler_fence` calls, the read of `IMPORTANT_VARIABLE` in `signal_handler`"] # [doc = " is *undefined behavior* due to a data race, despite everything happening in a single thread."] # [doc = " This is because the signal handler is considered to run concurrently with its associated"] # [doc = " thread, and explicit synchronization is required to pass data between a thread and its"] # [doc = " signal handler. The code below uses two `compiler_fence` calls to establish the usual"] # [doc = " release-acquire synchronization pattern (see [`fence`] for an image)."] # [doc = ""] # [doc = " ```"] # [doc = " use std::sync::atomic::AtomicBool;"] # [doc = " use std::sync::atomic::Ordering;"] # [doc = " use std::sync::atomic::compiler_fence;"] # [doc = ""] # [doc = " static mut IMPORTANT_VARIABLE: usize = 0;"] # [doc = " static IS_READY: AtomicBool = AtomicBool::new(false);"] # [doc = ""] # [doc = " fn main() {"] # [doc = "     unsafe { IMPORTANT_VARIABLE = 42 };"] # [doc = "     // Marks earlier writes as being released with future relaxed stores."] # [doc = "     compiler_fence(Ordering::Release);"] # [doc = "     IS_READY.store(true, Ordering::Relaxed);"] # [doc = " }"] # [doc = ""] # [doc = " fn signal_handler() {"] # [doc = "     if IS_READY.load(Ordering::Relaxed) {"] # [doc = "         // Acquires writes that were released with relaxed stores that we read from."] # [doc = "         compiler_fence(Ordering::Acquire);"] # [doc = "         assert_eq!(unsafe { IMPORTANT_VARIABLE }, 42);"] # [doc = "     }"] # [doc = " }"] # [doc = " ```"] # [inline] # [stable (feature = "compiler_fences" , since = "1.21.0")] # [rustc_diagnostic_item = "compiler_fence"] # [cfg_attr (miri , track_caller)] pub fn compiler_fence (order : Ordering) { unsafe { match order { Acquire => intrinsics :: atomic_singlethreadfence :: < { AO :: Acquire } > () , Release => intrinsics :: atomic_singlethreadfence :: < { AO :: Release } > () , AcqRel => intrinsics :: atomic_singlethreadfence :: < { AO :: AcqRel } > () , SeqCst => intrinsics :: atomic_singlethreadfence :: < { AO :: SeqCst } > () , Relaxed => panic ! ("there is no such thing as a relaxed fence") , } } }
}
